def majority_element(nums: list[int]) -> int:
    # Boyer-Moore Voting Algorithm O(N) time O(1) space
    candidate = None
    count = 0
    for num in nums:
        if count == 0:
            candidate = num
        count += (1 if num == candidate else -1)
    return candidate

