def max_coins(nums: list[int]) -> int:
    # Write your solution here
    nums = [1] + [n for n in nums if n > 0] + [1]
    n = len(nums)
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n):
        for left in range(0, n - length):
            right = left + length
            for k in range(left + 1, right):
                dp[left][right] = max(dp[left][right], nums[left] * nums[k] * nums[right] + dp[left][k] + dp[k][right])
    return dp[0][n - 1]

def alien_order(words: list[str]) -> str:
    # Write your solution here
    from collections import defaultdict
    adj = {c: set() for w in words for c in w}
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i + 1]
        min_len = min(len(w1), len(w2))
        if len(w1) > len(w2) and w1[:min_len] == w2[:min_len]: return ''
        for j in range(min_len):
            if w1[j] != w2[j]:
                adj[w1[j]].add(w2[j])
                break
    visit = {}
    res = []
    def dfs(c):
        if c in visit: return visit[c]
        visit[c] = True
        for nxt in adj[c]:
            if dfs(nxt): return True
        visit[c] = False
        res.append(c)
    for c in adj:
        if dfs(c): return ''
    return ''.join(res[::-1])

def ladder_length(beginWord: str, endWord: str, wordList: list[str]) -> int:
    # Write your solution here
    from collections import deque, defaultdict
    if endWord not in wordList: return 0
    L = len(beginWord)
    all_combo = defaultdict(list)
    for w in wordList:
        for i in range(L): all_combo[w[:i] + '*' + w[i+1:]].append(w)
    q = deque([(beginWord, 1)])
    visited = {beginWord}
    while q:
        word, level = q.popleft()
        for i in range(L):
            inter = word[:i] + '*' + word[i+1:]
            for neighbor in all_combo[inter]:
                if neighbor == endWord: return level + 1
                if neighbor not in visited:
                    visited.add(neighbor)
                    q.append((neighbor, level + 1))
            all_combo[inter] = []
    return 0

def shortest_path(grid: list[list[int]], k: int) -> int:
    # Write your solution here
    from collections import deque
    R, C = len(grid), len(grid[0])
    if k >= R + C - 2: return R + C - 2
    q = deque([(0, 0, k, 0)])
    visited = {(0, 0, k)}
    while q:
        r, c, rem_k, steps = q.popleft()
        if r == R - 1 and c == C - 1: return steps
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                next_k = rem_k - grid[nr][nc]
                if next_k >= 0 and (nr, nc, next_k) not in visited:
                    visited.add((nr, nc, next_k))
                    q.append((nr, nc, next_k, steps + 1))
    return -1

def is_match(s: str, p: str) -> bool:
    # Write your solution here
    cache = {}
    def dfs(i, j):
        if (i, j) in cache: return cache[(i, j)]
        if i >= len(s) and j >= len(p): return True
        if j >= len(p): return False
        match = i < len(s) and (s[i] == p[j] or p[j] == '.')
        if (j + 1) < len(p) and p[j + 1] == '*':
            cache[(i, j)] = dfs(i, j + 2) or (match and dfs(i + 1, j))
            return cache[(i, j)]
        if match:
            cache[(i, j)] = dfs(i + 1, j + 1)
            return cache[(i, j)]
        cache[(i, j)] = False
        return False
    return dfs(0, 0)

def get_medians(operations: list[int]) -> list[float]:
    # Write your solution here
    import heapq
    small, large = [], []
    res = []
    for num in operations:
        heapq.heappush(small, -num)
        if small and large and (-small[0] > large[0]):
            val = -heapq.heappop(small)
            heapq.heappush(large, val)
        if len(small) > len(large) + 1:
            val = -heapq.heappop(small)
            heapq.heappush(large, val)
        if len(large) > len(small):
            val = heapq.heappop(large)
            heapq.heappush(small, -val)
        if len(small) > len(large):
            res.append(float(-small[0]))
        else:
            res.append((-small[0] + large[0]) / 2.0)
    return res

def min_cut(s: str) -> int:
    # Write your solution here
    n = len(s)
    is_pal = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if s[i] == s[j] and (j - i <= 2 or is_pal[i + 1][j - 1]):
                is_pal[i][j] = True
    dp = [0] * n
    for i in range(n):
        if is_pal[0][i]: dp[i] = 0
        else:
            dp[i] = min(dp[j] + 1 for j in range(i) if is_pal[j + 1][i])
    return dp[-1]

def tree_diameter(n: int, edges: list[list[int]]) -> int:
    # Write your solution here
    from collections import defaultdict, deque
    if n <= 1: return 0
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v); adj[v].append(u)
    def bfs(start):
        dist = {start: 0}
        q = deque([start])
        farthest = start
        while q:
            node = q.popleft()
            for nxt in adj[node]:
                if nxt not in dist:
                    dist[nxt] = dist[node] + 1
                    farthest = nxt
                    q.append(nxt)
        return farthest, dist[farthest]
    node1, _ = bfs(0)
    node2, max_dist = bfs(node1)
    return max_dist
